/* Tough Cat 68 by sabbircoder07 — https://uiverse.io/sabbircoder07/tough-cat-68 */
.input__email {
  width: 100%;
  padding: 10px 18px;
  font-size: 14px;
  font-family: inherit;
  box-shadow: 0 0 0 1px #ffe3e3;
  border: none;
  border-radius: 20px;
  background-color: #fff5f5;
}

.input__email::placeholder {
  color: #ce9797;
  font-size: 12px;
}

.input__email:focus {
  outline: none;
  box-shadow: 0 0 0 1px #ffe3e3;
  border: none;
}
